// Times arrive from the server as UTC instants and are turned into words here, in the viewer's own
// timezone. Nothing about the viewer's clock is rendered server-side, so the HTML can be shared.

const LOCALE = "en-US"
const DAY_IN_MILLISECONDS = 24 * 60 * 60 * 1000

// Within this many calendar days we say "yesterday", "5 days ago" or "in 3 days". Beyond it, we name the date.
const RELATIVE_DAYS_LIMIT = 7

const relativeDays = new Intl.RelativeTimeFormat(LOCALE, { numeric: "auto" })
const formatters = new Map()

export function viewerTimeZone() {
  return Intl.DateTimeFormat().resolvedOptions().timeZone
}

// "1:42 PM", "yesterday", "5 days ago", "Sep 12", "tomorrow", "in 3 days", "Sep 12, 2024"
export function formatRelative(date, now = new Date(), timeZone = viewerTimeZone()) {
  const days = signedDifferenceInDays(now, date, timeZone)

  if (days === 0) {
    return formatClock(date, timeZone)
  } else if (Math.abs(days) <= RELATIVE_DAYS_LIMIT) {
    return relativeDays.format(days, "day")
  } else if (calendarParts(date, timeZone).year === calendarParts(now, timeZone).year) {
    return formatMonthDay(date, timeZone)
  } else {
    return formatDate(date, timeZone)
  }
}

// "1:42 PM"
export function formatClock(date, timeZone = viewerTimeZone()) {
  return formatWith({ hour: "numeric", minute: "2-digit", timeZone }, date)
}

// "Friday, September 12, 2025 at 1:42 PM EDT"
export function formatFullDateTime(date, timeZone = viewerTimeZone()) {
  return formatWith({
    weekday: "long", year: "numeric", month: "long", day: "numeric",
    hour: "numeric", minute: "2-digit", timeZoneName: "short", timeZone
  }, date)
}

// "Sep 12, 2025"
export function formatDate(date, timeZone = viewerTimeZone()) {
  return formatWith({ month: "short", day: "numeric", year: "numeric", timeZone }, date)
}

// "Sep 12"
export function formatMonthDay(date, timeZone = viewerTimeZone()) {
  return formatWith({ month: "short", day: "numeric", timeZone }, date)
}

// "Friday, September 12" from a calendar date such as "2025-09-12". A calendar date has no
// instant to convert, so it is always shown as written, whatever the viewer's timezone.
export function formatCalendarDate(isoDate) {
  return formatWith({ weekday: "long", month: "long", day: "numeric", timeZone: "UTC" }, new Date(isoDate))
}

export function signedDifferenceInDays(fromDate, toDate, timeZone = viewerTimeZone()) {
  return Math.round((beginningOfDay(toDate, timeZone) - beginningOfDay(fromDate, timeZone)) / DAY_IN_MILLISECONDS)
}

export function beginningOfDay(date, timeZone = viewerTimeZone()) {
  const { year, month, day } = calendarParts(date, timeZone)
  return new Date(Date.UTC(year, month - 1, day))
}

function calendarParts(date, timeZone) {
  return formatterFor({ year: "numeric", month: "numeric", day: "numeric", timeZone })
    .formatToParts(date)
    .reduce((parts, { type, value }) => {
      if (type !== "literal") parts[type] = parseInt(value, 10)
      return parts
    }, {})
}

// Some locales put a narrow no-break space before AM/PM. Normalize it so output is plain text.
function formatWith(options, date) {
  return formatterFor(options).format(date).replace(/\s/g, " ")
}

function formatterFor(options) {
  const key = JSON.stringify(options)

  if (!formatters.has(key)) {
    formatters.set(key, new Intl.DateTimeFormat(LOCALE, options))
  }

  return formatters.get(key)
}
EOF
