ROOT = "/app"
def edit(path, pairs)
  full = File.join(ROOT, path)
  text = File.read(full)
  pairs.each do |old, new|
    count = text.scan(old).size
    abort "#{path}: expected exactly 1 match, found #{count} for:\n#{old}" unless count == 1
    text = text.sub(old) { new }
  end
  File.write(full, text)
  puts "ok  #{path} (#{pairs.size} edit(s))"
end

